#!/usr/bin/env bash
set -Eeuo pipefail            # -e exit on error, -u unset var is error,
                              # -o pipefail pipeline fails if any stage fails
IFS=$'\n\t'                   # safer word splitting

log()  { printf '[%s] %s\n' "$(date +%T)" "$*" >&2; }
die()  { log "ERROR: $*"; exit 1; }
cleanup() { rm -rf "${TMPDIR_APP:-}"; }
trap cleanup EXIT             # always runs, even on failure
trap 'die "failed at line $LINENO"' ERR

command -v docker >/dev/null || die "docker is required"
: "${ENVIRONMENT:?ENVIRONMENT must be set}"     # fail if unset/empty

TMPDIR_APP="$(mktemp -d)"
main() {
  log "deploying to $ENVIRONMENT"
  # ...
}
main "$@"

// Jenkinsfile (declarative)
pipeline {
  agent { docker { image 'maven:3.9-eclipse-temurin-21' } }
  options { timeout(time: 30, unit: 'MINUTES'); disableConcurrentBuilds() }
  environment { REGISTRY = 'registry.example.com' }
  stages {
    stage('Build')  { steps { sh 'mvn -B -DskipTests package' } }
    stage('Test')   { steps { sh 'mvn -B test' }
                      post { always { junit 'target/surefire-reports/*.xml' } } }
    stage('Image')  { when { branch 'main' }
                      steps { sh 'docker build -t $REGISTRY/app:$GIT_COMMIT .' } }
    stage('Deploy') { when { branch 'main' }
                      steps {
                        input message: 'Deploy to production?'
                        withCredentials([string(credentialsId: 'kube-token', variable: 'TOKEN')]) {
                          sh './deploy.sh'
                        }
                      } }
  }
  post { failure { slackSend channel: '#ci', message: "Build failed: ${env.BUILD_URL}" } }
}

terraform {
  required_version = ">= 1.10"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 6.0" }
  }
}
provider "aws" {
  region = var.region
}
variable "region" {
  type    = string
  default = "ap-south-1"
}
variable "env" {
  type        = string
  description = "Deployment environment"
  validation {
    condition     = contains(["dev", "staging", "prod"], var.env)
    error_message = "env must be dev, staging or prod."
  }
}
variable "db_password" {
  type      = string
  sensitive = true
}
locals {
  name_prefix = "shop-${var.env}"
  tags        = { Project = "shop", Env = var.env, ManagedBy = "terraform" }
}
data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }
}
resource "aws_instance" "web" {
  ami           = data.aws_ami.al2023.id
  instance_type = "t3.micro"
  tags          = merge(local.tags, { Name = "${local.name_prefix}-web" })
}
output "web_ip" {
  value = aws_instance.web.public_ip
}

# for_each over a map: stable keys
variable "buckets" {
  type = map(object({ versioning = bool }))
  default = {
    logs    = { versioning = false }
    uploads = { versioning = true }
  }
}
resource "aws_s3_bucket" "this" {
  for_each = var.buckets
  bucket   = "myorg-${each.key}"
}
# count: positional (removing item 0 shifts the rest and may recreate them)
resource "aws_instance" "worker" {
  count         = var.env == "prod" ? 3 : 1       # conditional creation
  ami           = data.aws_ami.al2023.id
  instance_type = "t3.small"
}
# dynamic block: repeat nested blocks
resource "aws_security_group" "web" {
  name = "web"
  dynamic "ingress" {
    for_each = [80, 443]
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
  lifecycle {
    create_before_destroy = true      # replace without downtime
    prevent_destroy       = true      # guard critical resources
    ignore_changes        = [tags]    # tolerate external edits
  }
}

# /etc/nginx/conf.d/app.conf
upstream app_backend {
    least_conn;
    server 10.0.1.11:8080 max_fails=3 fail_timeout=10s;
    server 10.0.1.12:8080 max_fails=3 fail_timeout=10s;
    keepalive 32;
}
server {
    listen 80;
    server_name example.com www.example.com;
    return 301 https://example.com$request_uri;
}
server {
    listen 443 ssl;
    http2 on;
    server_name example.com;
    ssl_certificate     /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    add_header Strict-Transport-Security "max-age=31536000" always;
    gzip on;
    gzip_types text/css application/javascript application/json;

    location / {
        proxy_pass http://app_backend;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 60s;
    }
    location /static/ {
        root /var/www/app;
        expires 30d;
    }
}

# SPA fallback
server {
    listen 80;
    root /usr/share/nginx/html;
    index index.html;
    location / { try_files $uri $uri/ /index.html; }
    location ~* \.(js|css|png|svg|woff2)$ { expires 1y; add_header Cache-Control "public, immutable"; }
}
# Rate limiting (define zone in http {}, apply in location)
limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;
# location /api/ { limit_req zone=api burst=20 nodelay; proxy_pass http://app_backend; }
# Proxy cache
proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=cache:10m max_size=1g inactive=60m;
# location / { proxy_cache cache; proxy_cache_valid 200 10m; proxy_pass http://app_backend; }
# WebSocket upgrade headers
# proxy_set_header Upgrade $http_upgrade;
# proxy_set_header Connection "upgrade";
# Health check and status: stub_status; or use the load balancer's health checks

apiVersion: apps/v1
kind: Deployment
metadata: { name: api }
spec:
  replicas: 3
  selector: { matchLabels: { app: api } }
  strategy: { type: RollingUpdate, rollingUpdate: { maxSurge: 1, maxUnavailable: 0 } }
  template:
    metadata: { labels: { app: api } }
    spec:
      securityContext: { runAsNonRoot: true, seccompProfile: { type: RuntimeDefault } }
      containers:
      - name: api
        image: ghcr.io/myorg/api:sha-3f9c1d2
        ports: [{ containerPort: 8080 }]
        envFrom: [{ configMapRef: { name: api-config } }]
        resources:
          requests: { cpu: 100m, memory: 256Mi }
          limits: { memory: 256Mi }
        readinessProbe: { httpGet: { path: /ready, port: 8080 }, periodSeconds: 5 }
        livenessProbe: { httpGet: { path: /healthz, port: 8080 }, initialDelaySeconds: 15, periodSeconds: 10 }
        securityContext: { allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: { drop: ["ALL"] } }
---
apiVersion: v1
kind: Service
metadata: { name: api }
spec:
  selector: { app: api }
  ports: [{ port: 80, targetPort: 8080 }]

terraform {
  required_version = ">= 1.10"
  required_providers { aws = { source = "hashicorp/aws", version = "~> 6.0" } }
  backend "s3" {
    bucket       = "myorg-terraform-state"
    key          = "demo/terraform.tfstate"
    region       = "ap-south-1"
    encrypt      = true
    use_lockfile = true
  }
}
provider "aws" { region = "ap-south-1" }
variable "name" { type = string }
resource "aws_s3_bucket" "this" {
  bucket = var.name
  tags   = { ManagedBy = "terraform" }
}
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = "Enabled" }
}
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule { apply_server_side_encryption_by_default { sse_algorithm = "aws:kms" } }
}
resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
output "bucket_arn" { value = aws_s3_bucket.this.arn }
